<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue';import{useRoute}from'vue-router';import{api,apiMessage}from'@/api/client';import type{Plan,Tag,Task}from'@/types';
const route=useRoute();const planId=String(route.params.id);const plan=ref<Plan|null>(null);const tags=ref<Tag[]>([]);const tasks=ref<Task[]>([]);const error=ref('');const today=new Date().toLocaleDateString('sv-SE');
const tagDraft=reactive({name:'',color:'#002FA7'});const taskDraft=reactive({tagId:'',date:today,startTime:'09:00',endTime:'10:00',plannedMinutes:60,category:'CUSTOM',title:'',description:'',acceptanceText:'完成验收',resourceUrl:'',required:true,sortOrder:0});
const sortedTasks=computed(()=>[...tasks.value].sort((a,b)=>a.date.localeCompare(b.date)||a.sortOrder-b.sortOrder));
async function load(){const [plansResponse,tagsResponse,tasksResponse]=await Promise.all([api.get<Plan[]>('/plans'),api.get<Tag[]>(`/plans/${planId}/tags`),api.get<Task[]>(`/plans/${planId}/tasks`)]);plan.value=plansResponse.data.find(p=>p.id===planId)??null;tags.value=tagsResponse.data;tasks.value=tasksResponse.data;if(!taskDraft.tagId)taskDraft.tagId=tags.value.find(t=>!t.overall)?.id??tags.value[0]?.id??'';}
async function addTag(){try{await api.post(`/plans/${planId}/tags`,tagDraft);tagDraft.name='';await load();}catch(e){error.value=apiMessage(e);}}
async function addTask(){try{await api.post(`/plans/${planId}/tasks`,{...taskDraft,tagId:taskDraft.tagId||null,acceptance:taskDraft.acceptanceText.split('\n').map(v=>v.trim()).filter(Boolean)});Object.assign(taskDraft,{title:'',description:'',acceptanceText:'完成验收',resourceUrl:'',required:true});await load();}catch(e){error.value=apiMessage(e);}}
async function removeTask(task:Task){if(!confirm(`删除任务“${task.title}”？`))return;try{await api.delete(`/tasks/${task.id}`);await load();}catch(e){error.value=apiMessage(e);}}
onMounted(()=>load().catch(e=>error.value=apiMessage(e)));
</script>
<template><div class="page"><section class="page-head"><div><p class="eyebrow">PLAN / DETAIL</p><h1>{{plan?.name??'读取计划中…'}}</h1></div><p>{{plan?.startDate}}—{{plan?.endDate}} · {{tasks.length}} 项任务</p></section><p v-if="error" class="error-text">{{error}}</p><section class="tag-strip"><span v-for="tag in tags" :key="tag.id" class="tag" :style="{color:tag.color,borderColor:tag.color}">{{tag.name}}{{tag.overall?' · 总计':''}}</span><form class="inline-form" @submit.prevent="addTag"><input v-model="tagDraft.name" placeholder="新标签名称" required/><input v-model="tagDraft.color" type="color"/><button class="btn">添加标签</button></form></section><div class="split-layout split-layout--wide"><section class="section"><header class="section-title"><div><p class="eyebrow">TASK LEDGER</p><h2>计划任务</h2></div><span>{{tasks.length}}</span></header><article v-for="task in sortedTasks" :key="task.id" class="task-row compact"><div class="date-mini"><strong>{{task.date.slice(5)}}</strong><span>{{task.startTime?.slice(0,5)}}</span></div><div class="task-copy"><span class="tag" :style="{color:task.tagColor??'#002FA7',borderColor:task.tagColor??'#002FA7'}">{{task.tagName??'未分类'}}</span><h3>{{task.title}}</h3><p>{{task.description}}</p></div><div class="task-state"><strong>{{task.progress.status}}</strong><span>{{task.plannedMinutes}} 分钟</span></div><button class="btn danger" @click="removeTask(task)">删除</button></article><p v-if="!tasks.length" class="empty">使用右侧表单添加第一项任务。</p></section><form class="editor-card sticky" @submit.prevent="addTask"><p class="eyebrow">NEW TASK</p><h2>添加任务</h2><label>任务标题<input v-model="taskDraft.title" required/></label><label>任务内容<textarea v-model="taskDraft.description" rows="3"/></label><div class="form-grid"><label>日期<input v-model="taskDraft.date" type="date" :min="plan?.startDate" :max="plan?.endDate" required/></label><label>标签<select v-model="taskDraft.tagId"><option value="">未分类</option><option v-for="tag in tags" :key="tag.id" :value="tag.id">{{tag.name}}</option></select></label></div><div class="form-grid"><label>开始<input v-model="taskDraft.startTime" type="time"/></label><label>结束<input v-model="taskDraft.endTime" type="time"/></label></div><label>计划分钟<input v-model.number="taskDraft.plannedMinutes" type="number" min="1" required/></label><label>验收标准（每行一项）<textarea v-model="taskDraft.acceptanceText" rows="3"/></label><label>资料链接<input v-model="taskDraft.resourceUrl" type="url"/></label><label class="check"><input v-model="taskDraft.required" type="checkbox"/>计入核心完成率</label><button class="btn primary">保存任务</button></form></div></div></template>
